import {TEMPERAMENTS,ACTOR_VARIANTS} from './actor-profiles.mjs';
import {WORLD_CONDITIONS,CONDITION_PRESETS,conditionsOf,conditionLabel} from './world-conditions.mjs';
import {FACTION_SCENARIOS} from './actor-factions.mjs';
import {writeText,reconcileReadouts} from './actor-readouts.mjs';
import {SIMULATION_LIMITS} from './actor-catalog.mjs';
import {AFFINITY_KINDS,affinities} from './world-model.mjs';
import {encounterReport} from './outbreak-simulation.mjs';
export function createOutbreakPanel({container,toolbar,read,onOpen,onStep,onRun,onExample,onMatchup,onEquip,onBoost,onSpawn,onApply,onScenario,onRelationship,onReinforce,onProfile,onConditions}){
 const toggle=document.createElement('button');toggle.id='world-open';toggle.textContent='Outbreak';toolbar.append(toggle);const panel=document.createElement('section');panel.id='outbreak-panel';panel.innerHTML='<small class="outbreak-kicker">SHARED WORLD ACTORS</small><h2>Who would win?</h2><p>Connect scenes and run their inhabitants together. Equipment, abilities, terrain and relationships determine what happens.</p><details id="outbreak-new"><summary>New encounter</summary><div class="outbreak-start"><button id="outbreak-example">Zombies vs unarmed people</button><button id="outbreak-brooms">3 old ladies with brooms</button><button data-scenario="wizards">Wizard vs zombie horde</button><button data-scenario="rabbits">Rabbits & wolves</button><button data-scenario="ecosystem">Wizard, rabbits & zombies</button><button data-scenario="crowd">Crowd: 256 vs 256</button></div><label>Faction encounter<select id="outbreak-faction-scenario" aria-label="Faction encounter"></select></label><button id="outbreak-faction-load">Start faction encounter</button><small>Starts a new matchup. Undo restores your board.</small></details><div class="outbreak-time"><button id="outbreak-run">Run</button><button id="outbreak-step">Step 1s</button><select id="outbreak-speed" aria-label="Simulation speed"><option value="1">1×</option><option value="4" selected>4×</option><option value="12">12×</option></select></div><output id="outbreak-clock"></output><div id="outbreak-score"></div><p id="outbreak-result" role="status"></p><details id="outbreak-conditions"><summary>World conditions</summary><output id="outbreak-condition-state"></output><label>Preset<select id="outbreak-condition-preset" aria-label="Condition preset"></select></label><div id="outbreak-condition-fields"></div><button id="outbreak-condition-apply">Apply conditions</button><p>Manual world controls. Darkness, rain and fog reduce sight. Autumn and winter slow cold-sensitive actors; summer slows furry animals. Hardy actors resist cold; nightborn actors see in darkness. No automatic seasons, shelter seeking, fluid weather or building fire spread.</p></details><details id="outbreak-profiles"><summary>Temperament & variants</summary><label>Actor or entire scene<select id="outbreak-profile-target" aria-label="Actor or scene"></select></label><label>Temperament<select id="outbreak-temperament" aria-label="Temperament"></select></label><label>Variant<select id="outbreak-variant" aria-label="Actor variant"></select></label><button id="outbreak-profile-apply">Apply actor profile</button><output id="outbreak-profile-state"></output><p>Cautious armed actors flee below 70% health; steadfast at 5%; fearless stand until defeated. Unarmed actors still flee. Scout: faster, wider sight, less health. Hardy: more health, slower, cold resistant. Fireproof blocks fire damage. Switching preserves health percentage and never resurrects.</p></details><details id="outbreak-adjust"><summary>Change the odds</summary><div class="outbreak-pair"><button id="outbreak-add-zombies">Add 4 zombies</button><button id="outbreak-add-people">Add 4 people</button><button id="outbreak-boost-zombies">Stronger zombies</button><button id="outbreak-boost-people">Stronger people</button></div><button id="outbreak-arm">Give people brooms</button><label>Reinforce scene<select id="outbreak-spawn-scene" aria-label="Scene to reinforce"></select></label><select id="outbreak-spawn-count" aria-label="Reinforcement count"><option value="4">4 actors</option><option value="16">16 actors</option><option value="32">32 actors</option></select><button id="outbreak-reinforce">Add actors</button><small>Strength adds 2 health and 1 attack damage to survivors. Added actors use the scene’s original preset. No automatic resurrection.</small></details><details id="outbreak-diplomacy"><summary>Relationships</summary><p>Choose two groups of the same kind. Explicit relations override predation. Different memberships alone are neutral. Specific ties take precedence: family, tribe, politics, region, nation. Create groups under Object affinities, or load Two hostile nations.</p><select id="relation-a" aria-label="First group"></select><select id="relation-b" aria-label="Second group"></select><select id="relation-value" aria-label="Relationship"><option value="neutral">Neutral</option><option value="allied">Allied</option><option value="hostile">Hostile</option></select><button id="relation-save">Apply relationship</button><output id="relation-current"></output></details><details id="outbreak-admin"><summary>Admin overlays</summary><label><input id="outbreak-admin-enabled" type="checkbox"> Show health & actions in the world</label><output id="outbreak-perf"></output><div id="outbreak-actors"></div><details id="outbreak-memberships"><summary>Object affinities</summary><p>Membership belongs to each object and can inherit from its place. Different memberships alone do not create enemies.</p><select id="outbreak-entity" aria-label="Object to edit"></select><div id="outbreak-affinities"></div><button id="outbreak-affinity-save">Save affinities</button><label>Color actor rings by <select id="outbreak-color" aria-label="Affinity color"><option value="">None</option><option>familial</option><option>tribal</option><option>political</option><option>regional</option><option>national</option></select></label></details><details><summary>Rules & limits</summary><p>Fixed 250 ms steps. Yuka goal evaluators and a heap-based route search. Decisions and path expansions have fixed per-tick budgets. Connected regions reject unreachable destinations. Idle actors wander along reachable paths. No LLM calls.</p><p>Fireballs travel and collide with actors, terrain and conservative obstacle footprints. Splash can hurt allies; burning and mana are simulated. Obstacles use solid vertical footprints, not detailed roof geometry. Flames affect actors; building fire spread and destruction are not implemented.</p><p>512 active actors maximum; crowds use instanced models and health bars. Individual crowd actions remain in the actor list. Large populations may wait longer for a new decision or route. All active actors receive movement ticks. Offscreen coarse simulation, full crowd avoidance, cover and flight remain future work. Saves are batched every two seconds while running and flushed on pause. Hidden tabs pause without offline catch-up.</p></details></details><p id="outbreak-feedback" role="status"></p><details id="outbreak-recent"><summary>Recent events</summary><p id="outbreak-events"></p></details>';
 container.insertBefore(panel,container.querySelector('.drawer-head').nextSibling);const style=document.createElement('style');style.textContent='#outbreak-panel{padding:16px;background:var(--app-paper,#f3f0df);border-bottom:1px solid #b6bf9e;display:grid;gap:10px}#outbreak-panel h2{margin:0;font-size:25px;color:#2c382b}#outbreak-panel p{font-size:12px;line-height:1.5;margin:0}#outbreak-panel small,.outbreak-kicker{font-size:10px;color:#68745e}#outbreak-panel button{font-size:12px;padding:9px}#outbreak-panel details{border-top:1px solid #cbd1bc;padding-top:9px}#outbreak-panel summary{cursor:pointer;font-size:13px;font-weight:600;margin-bottom:9px}.outbreak-start{display:grid;gap:6px}.outbreak-start button:first-child{background:#455b3d;color:#fff}#outbreak-score{display:grid;grid-template-columns:1fr 1fr;gap:7px}#outbreak-score div{background:#fff9;padding:10px;border-radius:8px;display:grid}#outbreak-score strong{font-size:26px}#outbreak-score span{font-size:10px}.outbreak-time{display:flex;gap:6px}.outbreak-time button:first-child{flex:1}.outbreak-time select{width:60px}#outbreak-clock{font-size:11px;color:#647255}.outbreak-pair{display:grid;grid-template-columns:1fr 1fr;gap:5px}#outbreak-admin label{font-size:12px;display:flex;align-items:center;gap:8px}#outbreak-admin input[type=checkbox]{width:auto}#outbreak-affinities>div{padding:6px 0;border-bottom:1px solid #cbd1bc}#outbreak-affinities input:not([type=checkbox]){min-width:0;width:100%}#outbreak-affinities label:first-child{display:grid}#outbreak-entity{width:100%;margin:8px 0}#outbreak-perf{display:block;margin:10px 0;font-size:11px}#outbreak-actors{font-size:11px;line-height:1.7}#outbreak-result{font-weight:600;padding:6px;background:#e3e9d6;border-radius:5px}#sandbox-tools{flex-wrap:wrap;max-width:calc(100vw - 24px)}@media(max-width:799px){#sandbox-tools{max-width:calc(100vw - 72px)}}';document.head.append(style);
 const $=id=>panel.querySelector('#'+id);$('outbreak-new').open=!Object.keys(read().world?.actors||{}).length;let peak=0,entityKey='',groupKey='',sceneKey='',lastWorld=null,lastEntities=null,lastGroups=null,lastInstances=null,lastCards=null,lastProfileEntities=null,lastConditions=null,lastProfileState='',report=null;const actorNodes=new Map(),scores=new Map();
 const scoreFields=[['zombies','Zombies'],['people','People'],['rabbits','Rabbits'],['wolves','Wolves'],['eaten','Actors eaten'],['defeated','Actors defeated'],['casts','Spells cast'],['burning','Burning']];
 for(const [key,label]of scoreFields){const div=document.createElement('div'),strong=document.createElement('strong'),span=document.createElement('span');span.textContent=label;div.append(strong,span);$('outbreak-score').append(div);scores.set(key,strong);}
 for(const details of panel.querySelectorAll('details'))details.addEventListener('toggle',refresh);$('outbreak-admin-enabled').addEventListener('change',refresh);
 const options=(node,items)=>{for(const [value,label]of items){const o=document.createElement('option');o.value=value;o.textContent=label;node.append(o);}};
 options($('outbreak-faction-scenario'),Object.entries(FACTION_SCENARIOS));
 options($('outbreak-temperament'),Object.entries(TEMPERAMENTS).map(([id,x])=>[id,x.label]));options($('outbreak-variant'),Object.entries(ACTOR_VARIANTS).map(([id,x])=>[id,x.label]));
 options($('outbreak-condition-preset'),[...Object.entries(CONDITION_PRESETS).map(([id,x])=>[id,x.label]),['custom','Custom']]);
 for(const [key,values]of Object.entries(WORLD_CONDITIONS)){const label=document.createElement('label'),select=document.createElement('select');label.textContent=key==='timeOfDay'?'Time of day':key;select.id='condition-'+key;select.setAttribute('aria-label',label.textContent);options(select,values.map(v=>[v,v]));select.onchange=()=>{$('outbreak-condition-preset').value='custom';};label.append(select);$('outbreak-condition-fields').append(label);}
 function conditionInputs(c){for(const key of Object.keys(WORLD_CONDITIONS))$('condition-'+key).value=c[key];}
 function profileInputs(){const w=read().world,id=$('outbreak-profile-target').value,a=w.actors[id]||Object.values(w.actors).find(a=>a.instanceId===w.entities[id]?.instanceId);if(a){$('outbreak-temperament').value=a.temperament||'natural';$('outbreak-variant').value=a.variant||'standard';}}
 $('outbreak-profile-target').onchange=()=>{profileInputs();refresh();};
 $('outbreak-condition-preset').onchange=()=>{const preset=CONDITION_PRESETS[$('outbreak-condition-preset').value];if(preset)conditionInputs(preset);};
 for(const kind of AFFINITY_KINDS){const row=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),inherit=document.createElement('input'),inheritLabel=document.createElement('label');label.textContent=kind;input.id='affinity-'+kind;input.setAttribute('aria-label',kind+' memberships');input.placeholder='Names, separated by commas';inherit.type='checkbox';inherit.id='inherit-'+kind;inheritLabel.append(inherit,document.createTextNode('Inherit'));label.append(input);row.append(label,inheritLabel);$('outbreak-affinities').append(row);inherit.onchange=()=>input.disabled=inherit.checked;}
 function readAffinities(){const w=read().world,id=$('outbreak-entity').value,e=w?.entities[id];if(!e)return;for(const k of AFFINITY_KINDS){const inherited=!Object.hasOwn(e.affinities,k);$('inherit-'+k).checked=inherited;$('affinity-'+k).disabled=inherited;$('affinity-'+k).value=affinities(w,id,k).map(a=>w.groups[a.groupId]?.name||'').join(', ');}}
 $('outbreak-entity').onchange=readAffinities;
function open(){onOpen();container.querySelector('.drawer-head h2').textContent='World actors';container.scrollTop=0;refresh();}toggle.onclick=open;
 const action=fn=>async()=>{try{await fn();refresh();}catch(e){$('outbreak-feedback').textContent=e.message;}};
 $('outbreak-faction-load').onclick=action(async()=>{await onScenario($('outbreak-faction-scenario').value);$('outbreak-new').open=false;});
 $('outbreak-profile-apply').onclick=action(()=>onProfile($('outbreak-profile-target').value,{temperament:$('outbreak-temperament').value,variant:$('outbreak-variant').value}));
 $('outbreak-condition-apply').onclick=action(()=>onConditions(Object.fromEntries(Object.keys(WORLD_CONDITIONS).map(k=>[k,$('condition-'+k).value]))));
 $('outbreak-affinity-save').onclick=action(async()=>{await onApply($('outbreak-entity').value,AFFINITY_KINDS.map(kind=>({kind,inherit:$('inherit-'+kind).checked,names:$('affinity-'+kind).value.split(',').map(s=>s.trim()).filter(Boolean)})));$('outbreak-feedback').textContent='Object affinities saved.';readAffinities();});
 for(const b of panel.querySelectorAll('[data-scenario]'))b.onclick=action(async()=>{await onScenario(b.dataset.scenario);$('outbreak-new').open=false;});
 $('outbreak-reinforce').onclick=action(()=>onReinforce($('outbreak-spawn-scene').value,Number($('outbreak-spawn-count').value)));
 function relationRead(sync=true){const w=read().world,a=$('relation-a').value,b=$('relation-b').value,current=w?.relationships?.[[a,b].sort().join('|')];writeText($('relation-current'),current?'Saved: '+current:'No explicit relationship');if(sync)$('relation-value').value=current||'neutral';const disabled=read().busy||!a||!b||a===b||w.groups[a]?.kind!==w.groups[b]?.kind;if($('relation-save').disabled!==disabled)$('relation-save').disabled=disabled;}
 $('relation-a').onchange=()=>relationRead();$('relation-b').onchange=()=>relationRead();
 $('relation-save').onclick=action(async()=>{await onRelationship($('relation-a').value,$('relation-b').value,$('relation-value').value);relationRead();});
 $('outbreak-run').onclick=action(onRun);$('outbreak-step').onclick=action(()=>onStep(1));$('outbreak-example').onclick=action(async()=>{await onExample();$('outbreak-new').open=false;});$('outbreak-brooms').onclick=action(async()=>{await onMatchup();$('outbreak-new').open=false;});$('outbreak-add-zombies').onclick=action(()=>onSpawn('undead'));$('outbreak-add-people').onclick=action(()=>onSpawn('living'));$('outbreak-boost-zombies').onclick=action(()=>onBoost('undead'));$('outbreak-boost-people').onclick=action(()=>onBoost('living'));$('outbreak-arm').onclick=action(onEquip);
 function refresh(){
 const {world,board,running,busy,cost}=read();if(!world?.encounter)return;
 if(lastConditions!==world.conditions||!$('outbreak-condition-state').textContent){lastConditions=world.conditions;const conditions=conditionsOf(world);conditionInputs(conditions);$('outbreak-condition-preset').value=Object.keys(CONDITION_PRESETS).find(id=>Object.keys(WORLD_CONDITIONS).every(k=>CONDITION_PRESETS[id][k]===conditions[k]))||'custom';writeText($('outbreak-condition-state'),conditionLabel(world));}
 if($('outbreak-profiles').open){
  if(lastProfileEntities!==world.entities){lastProfileEntities=world.entities;const items=Object.values(world.entities).filter(e=>e.active&&(world.actors[e.id]||e.kind==='place'&&Object.values(world.actors).some(a=>a.instanceId===e.instanceId))),selected=$('outbreak-profile-target').value;$('outbreak-profile-target').replaceChildren();options($('outbreak-profile-target'),items.map(e=>[e.id,(e.kind==='place'?'Scene · ':'Actor · ')+e.name]));if(items.some(e=>e.id===selected))$('outbreak-profile-target').value=selected;profileInputs();}
  const id=$('outbreak-profile-target').value,actors=Object.values(world.actors).filter(a=>a.id===id||world.entities[id]?.kind==='place'&&a.instanceId===world.entities[id].instanceId),a=actors[0],profileState=JSON.stringify([id,a?.temperament,a?.variant]);if(profileState!==lastProfileState){lastProfileState=profileState;profileInputs();}writeText($('outbreak-profile-state'),a?actors.length+(actors.length===1?' actor: ':' actors · first: ')+(a.temperament||'natural')+' / '+(a.variant||'standard')+' · sight '+a.sense.toFixed(1)+' m · speed '+a.speed.toFixed(2)+' m/s':'Choose a populated actor scene.');
 }
 // Closed inspectors do not sort hundreds of semantic objects or construct actor rows.
 if($('outbreak-admin').open&&$('outbreak-memberships').open&&lastEntities!==world.entities){
  lastEntities=world.entities;const entities=Object.values(world.entities).filter(e=>e.active).sort((a,b)=>(a.kind==='person'?-1:a.kind==='place'?0:1)-(b.kind==='person'?-1:b.kind==='place'?0:1)||a.name.localeCompare(b.name)),key=JSON.stringify(entities.map(e=>[e.id,e.name]));
  if(key!==entityKey){entityKey=key;const selected=$('outbreak-entity').value;$('outbreak-entity').replaceChildren(...entities.map(e=>{const o=document.createElement('option');o.value=e.id;o.textContent=e.kind+' · '+e.name;return o;}));if(entities.some(e=>e.id===selected))$('outbreak-entity').value=selected;readAffinities();}else readAffinities();
 }
 if($('outbreak-diplomacy').open){
  if(lastGroups!==world.groups){lastGroups=world.groups;const groups=Object.values(world.groups),gkey=JSON.stringify(groups.map(g=>[g.id,g.name]));if(gkey!==groupKey){groupKey=gkey;for(const id of ['relation-a','relation-b']){const selected=$(id).value;$(id).replaceChildren(...groups.map(g=>{const o=document.createElement('option');o.value=g.id;o.textContent=g.kind+' · '+g.name;return o;}));if(groups.some(g=>g.id===selected))$(id).value=selected;}const left=world.groups[$('relation-a').value],right=world.groups[$('relation-b').value];if(!left||!right||left.id===right.id||left.kind!==right.kind){const saved=Object.keys(world.relationships||{}).map(k=>k.split('|')).find(pair=>pair.every(id=>world.groups[id])),pair=saved||groups.flatMap(a=>groups.filter(b=>a.id!==b.id&&a.kind===b.kind).map(b=>[a.id,b.id]))[0];if(pair){$('relation-a').value=pair[0];$('relation-b').value=pair[1];}}relationRead();}}
  relationRead(false);
 }
 if($('outbreak-adjust').open&&(lastInstances!==board?.instances||lastCards!==board?.cards)){lastInstances=board?.instances;lastCards=board?.cards;const scenes=(board?.instances||[]).filter(i=>board.cards[i.cardId+'@'+i.cardRevision]?.recipe?.agents),skey=JSON.stringify(scenes.map(i=>[i.instanceId,board.cards[i.cardId+'@'+i.cardRevision].name]));if(skey!==sceneKey){sceneKey=skey;const selected=$('outbreak-spawn-scene').value;$('outbreak-spawn-scene').replaceChildren(...scenes.map(i=>{const o=document.createElement('option');o.value=i.instanceId;o.textContent=board.cards[i.cardId+'@'+i.cardRevision].name||i.instanceId;return o;}));if(scenes.some(i=>i.instanceId===selected))$('outbreak-spawn-scene').value=selected;}}
 if(lastWorld!==world){lastWorld=world;report=encounterReport(world,{includeActors:false});for(const [key]of scoreFields)writeText(scores.get(key),report[key]);const r=report,hasActors=Object.values(world.actors||{}).some(a=>world.entities[a.id]?.active);writeText($('outbreak-result'),!hasActors?'Add scenes or choose a matchup.':!r.active?'No survivors.':r.fighting?'Combat in progress.':r.projectiles?'Projectiles in flight.':r.fleeing?'Actors are fleeing.':r.blocked?'Some actors are blocked or cornered.':'Actors are alive; no combat this tick.');}
 const r=report;peak=Math.max(peak,cost||0);writeText($('outbreak-clock'),r.time.toFixed(1)+' simulation seconds · '+(running?'Running':'Paused'));writeText($('outbreak-run'),running?'Pause':'Run');
 if($('outbreak-admin').open){writeText($('outbreak-perf'),'Advance '+(cost||0).toFixed(1)+' ms · peak '+peak.toFixed(1)+' ms (excludes render / save) · '+r.active+'/'+SIMULATION_LIMITS.actors+' actors · '+(r.metrics.decisions||0)+' decisions · '+(r.metrics.pathExpansions||0)+' path expansions · '+(r.metrics.queued||0)+' queued · 0 LLM calls');
  reconcileReadouts($('outbreak-actors'),$('outbreak-admin-enabled').checked?Object.values(world.actors||{}).filter(a=>world.entities[a.id]?.active).map(a=>({id:a.id,text:a.name+' · '+a.hp+'/'+a.maxHp+' HP · '+a.intent+(a.targetId?' → '+world.entities[a.targetId]?.name:'')+' · '+(a.weapon||'unarmed')+' · '+(a.temperament||'natural')+' / '+(a.variant||'standard')})):[],actorNodes);
 }
 if($('outbreak-recent').open)writeText($('outbreak-events'),world.encounter.events.slice(0,5).map(e=>e.at.toFixed(1)+'s · '+e.text).join(' / ')||'No attacks resolved yet.');
 for(const b of panel.querySelectorAll('[data-scenario]'))if(b.disabled!==busy)b.disabled=busy;
 for(const id of ['outbreak-faction-load','outbreak-profile-apply','outbreak-condition-apply','outbreak-reinforce','outbreak-example','outbreak-brooms','outbreak-step','outbreak-add-zombies','outbreak-add-people','outbreak-boost-zombies','outbreak-boost-people','outbreak-arm'])if($(id).disabled!==busy)$(id).disabled=busy;
 }

 return {open,refresh,speed:()=>Number($('outbreak-speed').value),admin:()=>$('outbreak-admin-enabled').checked,view:()=>({colorKind:$('outbreak-color').value}),feedback:t=>$('outbreak-feedback').textContent=t};
}
